create table if not exists public.krim_country_pack_events (
 id bigint generated by default as identity primary key,pack_id bigint not null references public.krim_country_operating_packs(id) on delete restrict,
 actor_user_id uuid,old_status text,new_status text not null,rationale text not null,created_at timestamptz not null default now()
);
alter table public.krim_country_pack_events enable row level security;
alter table public.krim_country_pack_events force row level security;
revoke all on public.krim_country_pack_events from anon,authenticated;
revoke all on sequence public.krim_country_pack_events_id_seq from anon,authenticated;
create or replace function public.krim_admin_set_country_pack_status(p_pack_id bigint,p_status text,p_rationale text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); p public.krim_country_operating_packs%rowtype; total_n integer; approved_n integer;
begin
 if u is null or coalesce(auth.jwt()->>'aal','')<>'aal2' or not private.krim_has_permission(u,1::bigint,'admin.platform') then raise exception using errcode='42501',message='AAL2 platform administrator access required'; end if;
 if p_status not in('research_pending','in_review','approved','suspended') or nullif(btrim(p_rationale),'') is null then raise exception using errcode='22023',message='Invalid pack status or missing rationale'; end if;
 select * into p from public.krim_country_operating_packs where id=p_pack_id for update; if not found then raise exception using errcode='P0002',message='Country pack not found'; end if;
 select count(*),count(*) filter(where review_status='approved' and applicability in('yes','no','conditional') and source_id is not null and nullif(btrim(evidence_reference),'') is not null and nullif(btrim(reviewer_note),'') is not null and (expires_at is null or expires_at>now())) into total_n,approved_n from public.krim_country_pack_controls where pack_id=p_pack_id and mandatory;
 if p_status='approved' and (total_n=0 or total_n<>approved_n) then raise exception using errcode='22023',message='Country pack cannot be approved until every mandatory control is approved with current evidence'; end if;
 update public.krim_country_operating_packs set pack_status=p_status,updated_at=now() where id=p_pack_id;
 insert into public.krim_country_pack_events(pack_id,actor_user_id,old_status,new_status,rationale) values(p_pack_id,u,p.pack_status,p_status,btrim(p_rationale));
 return jsonb_build_object('success',true,'pack_id',p_pack_id,'pack_status',p_status,'mandatory_controls',total_n,'approved_controls',approved_n);
end $$;
revoke all on function public.krim_admin_set_country_pack_status(bigint,text,text) from public,anon;
grant execute on function public.krim_admin_set_country_pack_status(bigint,text,text) to authenticated;